Looking at this logic puzzle, I need to find a valid assignment of people, house colors, pets, drinks, and hobbies to 5 houses that satisfies all 17 constraints.

I'll use a brute-force approach with permutations, checking all constraints for each candidate solution. This is feasible because the constraint checker will quickly reject invalid combinations.

```python
from itertools import permutations

people = ['Blake', 'Finley', 'Quinn', 'Riley', 'Sawyer']
colors = ['blue', 'orange', 'red', 'white', 'yellow']
pets = ['cat', 'dog', 'fish', 'horse', 'rabbit']
drinks = ['cocoa', 'coffee', 'juice', 'milk', 'water']
hobbies = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

def check_all_constraints(houses):
    """Check all 17 constraints. houses is a list of 5 dicts."""
    for i in range(5):
        h = houses[i]

        # Constraint 1: coffee drinker next to blue house
        if h['drink'] == 'coffee':
            has_blue = (i > 0 and houses[i-1]['color'] == 'blue') or \
                       (i < 4 and houses[i+1]['color'] == 'blue')
            if not has_blue:
                return False

        # Constraint 2: fencing immediately left of fish
        if h['pet'] == 'fish':
            if i == 0 or houses[i-1]['hobby'] != 'fencing':
                return False

        # Constraint 3: hiking immediately left of Sawyer
        if h['person'] == 'Sawyer':
            if i == 0 or houses[i-1]['hobby'] != 'hiking':
                return False

        # Constraint 4: juice drinker is dog owner
        if h['drink'] == 'juice' and h['pet'] != 'dog':
            return False

        # Constraint 5: orange house = water drinker
        if h['color'] == 'orange' and h['drink'] != 'water':
            return False

        # Constraint 6: juice drinker not in white house
        if h['drink'] == 'juice' and h['color'] == 'white':
            return False

        # Constraint 7: horse owner next to Quinn
        if h['pet'] == 'horse':
            has_quinn = (i > 0 and houses[i-1]['person'] == 'Quinn') or \
                        (i < 4 and houses[i+1]['person'] == 'Quinn')
            if not has_quinn:
                return False

        # Constraint 8: cocoa immediately left of red house
        if h['color'] == 'red':
            if i == 0 or houses[i-1]['drink'] != 'cocoa':
                return False

        # Constraint 9: white house next to fish owner
        if h['color'] == 'white':
            has_fish = (i > 0 and houses[i-1]['pet'] == 'fish') or \
                       (i < 4 and houses[i+1]['pet'] == 'fish')
            if not has_fish:
                return False

        # Constraint 10: Blake immediately left of red house
        if h['person'] == 'Blake':
            if i == 4 or houses[i+1]['color'] != 'red':
                return False

        # Constraint 11: milk immediately left of rabbit owner
        if h['pet'] == 'rabbit':
            if i == 0 or houses[i-1]['drink'] != 'milk':
                return False

        # Constraint 12: Sawyer next to white house
        if h['person'] == 'Sawyer':
            has_white = (i > 0 and houses[i-1]['color'] == 'white') or \
                        (i < 4 and houses[i+1]['color'] == 'white')
            if not has_white:
                return False

        # Constraint 13: Finley not in orange house
        if h['person'] == 'Finley' and h['color'] == 'orange':
            return False

        # Constraint 14: painting person owns fish
        if h['pet'] == 'fish' and h['hobby'] != 'painting':
            return False

        # Constraint 15: water drinker owns rabbit
        if h['drink'] == 'water' and h['pet'] != 'rabbit':
            return False

        # Constraint 16: Finley doesn't do chess
        if h['person'] == 'Finley' and h['hobby'] == 'chess':
            return False

        # Constraint 17: Riley immediately left of rowing person
        if h['person'] == 'Riley':
            if i == 4 or houses[i+1]['hobby'] != 'rowing':
                return False

    return True

def solve():
    for people_perm in permutations(people):
        for colors_perm in permutations(colors):
            for pets_perm in permutations(pets):
                for drinks_perm in permutations(drinks):
                    for hobbies_perm in permutations(hobbies):
                        houses = [
                            {
                                'person': people_perm[i],
                                'color': colors_perm[i],
                                'pet': pets_perm[i],
                                'drink': drinks_perm[i],
                                'hobby': hobbies_perm[i]
                            }
                            for i in range(5)
                        ]

                        if check_all_constraints(houses):
                            for house in houses:
                                if house['pet'] == 'rabbit':
                                    return house['person']

    return None

answer = solve()
print(answer)
